package app

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/signal"
	"strings"

	"github.com/emergingrobotics/ghax/internal/agent"
	"github.com/emergingrobotics/ghax/internal/session"
	"github.com/emergingrobotics/ghax/internal/terminal"
)

const footerHint = "enter send · /help · ^C interrupt · ^D exit"

// Interactive runs the REPL. On a terminal it renders a styled UI (cleared
// screen, header, boxed prompt, footer); when output is piped it falls back to
// a plain prompt so scripts and tests are unaffected. It streams the model's
// answer as it arrives and persists the session after each turn.
func (a *App) Interactive(ctx context.Context) error {
	st := terminal.Detect(os.Stdout)
	if !st.Color {
		return a.interactivePlain(ctx)
	}
	return a.interactiveStyled(ctx, st)
}

func (a *App) interactiveStyled(ctx context.Context, st terminal.Styler) error {
	out := os.Stdout
	width := terminal.Width()

	fmt.Fprint(out, st.ClearScreen())
	fmt.Fprint(out, a.headerBox(st, width))
	fmt.Fprintln(out, st.Dim(footerHint))
	a.herdr.ReportStatus(agent.StatusIdle)

	reader := bufio.NewReader(os.Stdin)
	for {
		fmt.Fprintln(out)
		fmt.Fprintln(out, st.PromptTop(width))
		fmt.Fprint(out, st.Dim("│ ")+st.Cyan("› "))

		line, err := reader.ReadString('\n')
		if err == io.EOF {
			fmt.Fprintln(out, "\n"+st.Dim("bye"))
			return nil
		}
		if err != nil {
			return err
		}
		fmt.Fprintln(out, st.PromptBottom(width))

		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "/") {
			if a.slash(ctx, out, st, width, line) {
				return nil
			}
			continue
		}

		fmt.Fprint(out, "\n"+st.Bold(st.Magenta("ghax"))+"\n")
		err = a.runInterruptible(ctx, line, a.styledHooks(out, st))
		fmt.Fprintln(out)
		switch {
		case errors.Is(err, context.Canceled):
			fmt.Fprintln(out, st.Dim("(interrupted)"))
		case err != nil:
			fmt.Fprintln(out, st.Red("error: "+err.Error()))
		}
		if serr := a.save(); serr != nil {
			fmt.Fprintln(os.Stderr, "ghax: warning: could not save session:", serr)
		}
	}
}

// headerBox renders the top chrome: model, provider, shape, and a status dot.
func (a *App) headerBox(st terminal.Styler, width int) string {
	m := a.deps.Provider.Model()
	shape := a.shape
	if shape == "" {
		shape = "default"
	}
	var b strings.Builder
	b.WriteString(st.TitledTop("ghax", width) + "\n")
	b.WriteString(st.Row("", "", m.Name+" · "+m.Provider+" · "+shape, width) + "\n")
	b.WriteString(st.Row(st.Green("●")+" ", "● ", "idle", width) + "\n")
	b.WriteString(st.Bottom(width) + "\n")
	return b.String()
}

// styledHooks streams the answer flush-left: assistant text is written as-is,
// tool activity is shown dim, and errors in red. No line is indented.
func (a *App) styledHooks(out io.Writer, st terminal.Styler) agent.DriverHooks {
	return agent.DriverHooks{
		OnAssistantDelta: func(s string) { io.WriteString(out, s) },
		OnToolCall: func(c agent.ToolCall) {
			fmt.Fprintf(out, "\n%s\n", st.Dim("· "+c.Name+" "+summarizeArgs(c.Args)))
		},
		OnToolResult: func(r agent.ToolResult) {
			if r.IsError {
				fmt.Fprintf(out, "\n%s\n", st.Red("! "+firstLine(r.Content)))
			}
		},
		OnStatus: func(s agent.AgentStatus) { a.herdr.ReportStatus(s) },
	}
}

// runInterruptible runs one user-turn that Ctrl-C cancels without exiting the
// REPL. Outside a turn the signal handler is removed, so Ctrl-C at the prompt
// exits via the default disposition.
func (a *App) runInterruptible(base context.Context, line string, hooks agent.DriverHooks) error {
	ctx, cancel := context.WithCancel(base)
	defer cancel()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt)
	defer signal.Stop(sigCh)
	go func() {
		select {
		case <-sigCh:
			cancel()
		case <-ctx.Done():
		}
	}()

	out, err := agent.Run(ctx, a.log, a.deps, agent.UserInput{Text: line}, hooks)
	a.usage.Add(out.Usage)
	return err
}

// interactivePlain is the unstyled REPL used when output is not a terminal.
func (a *App) interactivePlain(ctx context.Context) error {
	out := os.Stdout
	fmt.Fprintf(out, "ghax — %s via %s. /help for commands, Ctrl-D to exit.\n",
		a.deps.Provider.Model().Name, a.deps.Provider.Model().Provider)
	a.herdr.ReportStatus(agent.StatusIdle)

	reader := bufio.NewReader(os.Stdin)
	for {
		fmt.Fprint(out, "ghax> ")
		line, err := reader.ReadString('\n')
		if err == io.EOF {
			fmt.Fprintln(out)
			return nil
		}
		if err != nil {
			return err
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "/") {
			if a.slash(ctx, out, terminal.Styler{}, terminal.Width(), line) {
				return nil
			}
			continue
		}
		outcome, err := agent.Run(ctx, a.log, a.deps, agent.UserInput{Text: line}, a.hooks(out, os.Stderr))
		a.usage.Add(outcome.Usage)
		if err != nil {
			fmt.Fprintf(os.Stderr, "\nghax: %v\n", err)
		}
		fmt.Fprintln(out)
		if err := a.save(); err != nil {
			fmt.Fprintln(os.Stderr, "ghax: warning: could not save session:", err)
		}
	}
}

// slash handles REPL commands. It returns true when the REPL should exit. st
// and width drive the styled redraw for /clear; ctx bounds /compact's model
// call. In the plain (non-terminal) REPL st is a disabled Styler.
func (a *App) slash(ctx context.Context, out io.Writer, st terminal.Styler, width int, line string) (exit bool) {
	switch strings.Fields(line)[0] {
	case "/exit", "/quit":
		return true
	case "/help":
		fmt.Fprint(out, "commands:\n"+
			"/help        show this help\n"+
			"/clear       start a fresh conversation\n"+
			"/compact     summarize history to free up context\n"+
			"/usage       show this session's token usage\n"+
			"/copy        copy the last response to the clipboard\n"+
			"/session     show the current session id\n"+
			"/exit, /quit leave (or press Ctrl-D)\n")
	case "/clear":
		a.clearConversation(out, st, width)
	case "/compact":
		a.compact(ctx, out, st)
	case "/usage":
		a.showUsage(out)
	case "/copy":
		a.copyLast(out, st)
	case "/session":
		fmt.Fprintf(out, "session %s (resume with: ghax --resume=%s)\n", a.SessionID(), a.SessionID())
	default:
		fmt.Fprintf(out, "unknown command %q; /help for the list\n", line)
	}
	return false
}

// clearConversation drops the conversation and starts a fresh session. On a
// terminal it redraws the cleared UI; otherwise it prints a note.
func (a *App) clearConversation(out io.Writer, st terminal.Styler, width int) {
	a.log = agent.NewLog()
	a.meta = session.Meta{ID: session.NewID(), Cwd: a.cwd, Shape: a.shape}
	if st.Color {
		fmt.Fprint(out, st.ClearScreen())
		fmt.Fprint(out, a.headerBox(st, width))
		fmt.Fprintln(out, st.Dim(footerHint))
		return
	}
	fmt.Fprintln(out, "cleared. new session "+a.SessionID())
}

// compact summarizes the current history into a seed, freeing context. The
// summary is produced by the active provider, so it works on local models too.
func (a *App) compact(ctx context.Context, out io.Writer, st terminal.Styler) {
	if a.log.Len() == 0 {
		fmt.Fprintln(out, st.Dim("nothing to compact"))
		return
	}
	before := agent.EstimateTokens(a.log.Window())
	fmt.Fprintln(out, st.Dim("compacting…"))
	if err := agent.Compact(ctx, a.log, a.summarizer()); err != nil {
		fmt.Fprintln(out, st.Red("compact failed: "+err.Error()))
		return
	}
	after := agent.EstimateTokens(a.log.Window())
	fmt.Fprintln(out, st.Dim(fmt.Sprintf("compacted history (~%d → ~%d tokens)", before, after)))
	if err := a.save(); err != nil {
		fmt.Fprintln(os.Stderr, "ghax: warning: could not save session:", err)
	}
}

// showUsage prints the session's accumulated token usage. The counts come from
// each provider response (LiteLLM forwards Ollama's counts), so this works on
// local providers; a provider that reports no usage shows zeros.
func (a *App) showUsage(out io.Writer) {
	m := a.deps.Provider.Model()
	u := a.usage
	fmt.Fprintf(out, "session usage — %s (%s)\n", m.Name, m.Provider)
	fmt.Fprintf(out, "tokens: %d in + %d out = %d total\n",
		u.InputTokens, u.OutputTokens, u.InputTokens+u.OutputTokens)
}

// copyLast copies the last assistant response to the system clipboard.
func (a *App) copyLast(out io.Writer, st terminal.Styler) {
	text := a.lastAssistantText()
	if text == "" {
		fmt.Fprintln(out, st.Dim("no response to copy"))
		return
	}
	if err := copyToClipboard(text); err != nil {
		fmt.Fprintln(out, st.Red("copy failed: "+err.Error()))
		return
	}
	fmt.Fprintln(out, st.Dim(fmt.Sprintf("copied %d chars to clipboard", len(text))))
}

func (a *App) lastAssistantText() string {
	items := a.log.Items()
	for i := len(items) - 1; i >= 0; i-- {
		if items[i].Kind == agent.ItemAssistantText {
			return items[i].Text
		}
	}
	return ""
}

// Package config holds ghax's durable settings and the shape definitions that
// configure the engine for a job. It is plain data: it parses config files and
// resolves the effective run settings, but it never imports the provider,
// tool, or driver packages, so the dependency graph stays acyclic.
package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// LoopMode selects which driver runs a shape.
type LoopMode string

const (
	LoopInteractive LoopMode = "interactive"
	LoopOneshot     LoopMode = "oneshot"
	LoopObserve     LoopMode = "observe"
)

// ProviderConfig describes one model backend. Type selects the adapter family;
// the rest is endpoint and auth detail. A static endpoint variant is a config
// block, never a new Go type.
type ProviderConfig struct {
	Type      string            `json:"type"`                  // openai | anthropic | local
	BaseURL   string            `json:"base_url,omitempty"`    // endpoint root
	APIKeyEnv string            `json:"api_key_env,omitempty"` // env var holding the key
	Model     string            `json:"model,omitempty"`       // default model for this provider
	Headers   map[string]string `json:"headers,omitempty"`     // extra request headers
	// Params are extra request-body fields merged into each request (sampling
	// controls such as temperature, top_p, top_k, repetition_penalty). They are
	// passed through verbatim, so backend-specific keys (forwarded by an
	// OpenAI-compatible proxy like LiteLLM) work without adapter changes.
	Params map[string]any `json:"params,omitempty"`
}

// ObserveConfig wires an observe shape: where events come from, what fires a
// reaction, and the prompt template that runs when one does.
type ObserveConfig struct {
	Source  SourceConfig  `json:"source"`
	Trigger TriggerConfig `json:"trigger"`
	Prompt  string        `json:"prompt"` // may contain {{.Event}}
}

// SourceConfig selects an observe source.
type SourceConfig struct {
	Kind    string   `json:"kind"`              // stdin | file | exec
	Path    string   `json:"path,omitempty"`    // file source
	Command []string `json:"command,omitempty"` // exec source
}

// TriggerConfig selects when a reaction fires.
type TriggerConfig struct {
	Kind       string `json:"kind"`                  // every | match
	Pattern    string `json:"pattern,omitempty"`     // regexp for match
	DebounceMS int    `json:"debounce_ms,omitempty"` // coalesce rapid events
}

// Shape is a named bundle that configures the engine for one job. Shapes are
// files kept in a repo; they double as subagent roles for the task tool.
type Shape struct {
	Name       string         `json:"name"`
	Loop       LoopMode       `json:"loop"`
	Provider   string         `json:"provider,omitempty"`
	Model      string         `json:"model,omitempty"`
	Effort     string         `json:"effort,omitempty"`
	System     string         `json:"system,omitempty"`       // appended to the base prompt
	SystemFile string         `json:"system_file,omitempty"`  // @file alternative to System
	Tools      []string       `json:"tools,omitempty"`        // enabled tool names (empty = all core)
	Skills     []string       `json:"skills,omitempty"`       // SKILL.md dirs to load
	Instr      []string       `json:"instructions,omitempty"` // project instruction files
	MaxTurns   int            `json:"max_turns,omitempty"`
	Observe    *ObserveConfig `json:"observe,omitempty"`
}

// Config is the whole durable configuration.
type Config struct {
	DefaultProvider string                    `json:"default_provider"`
	DefaultShape    string                    `json:"default_shape,omitempty"`
	SystemBase      string                    `json:"system_base"`
	Providers       map[string]ProviderConfig `json:"providers"`
	Shapes          map[string]Shape          `json:"shapes,omitempty"`
}

// Path returns the config file location, honoring GHAX_CONFIG then XDG.
func Path() (string, error) {
	if p := os.Getenv("GHAX_CONFIG"); p != "" {
		return p, nil
	}
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "ghax", "config.json"), nil
}

// Load reads and merges the config file over the built-in defaults. A missing
// file is not an error: the defaults stand.
func Load() (*Config, error) {
	cfg := Default()
	path, err := Path()
	if err != nil {
		return cfg, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return cfg, nil
		}
		return nil, fmt.Errorf("read config %s: %w", path, err)
	}
	if err := merge(cfg, data); err != nil {
		return nil, fmt.Errorf("parse config %s: %w", path, err)
	}
	return cfg, nil
}

// merge decodes user config over the defaults. User-provided maps replace the
// corresponding default entries key by key; scalar fields override when set.
func merge(cfg *Config, data []byte) error {
	var user Config
	if err := json.Unmarshal(data, &user); err != nil {
		return err
	}
	if user.DefaultProvider != "" {
		cfg.DefaultProvider = user.DefaultProvider
	}
	if user.DefaultShape != "" {
		cfg.DefaultShape = user.DefaultShape
	}
	if user.SystemBase != "" {
		cfg.SystemBase = user.SystemBase
	}
	for name, p := range user.Providers {
		cfg.Providers[name] = p
	}
	if cfg.Shapes == nil {
		cfg.Shapes = map[string]Shape{}
	}
	for name, s := range user.Shapes {
		s.Name = name
		cfg.Shapes[name] = s
	}
	return nil
}

// Package provider builds a concrete agent.Provider from resolved config. It
// depends on the adapter subpackages and on config; config never depends on it,
// keeping the graph acyclic.
package provider

import (
	"context"
	"fmt"

	"github.com/emergingrobotics/ghax/internal/agent"
	"github.com/emergingrobotics/ghax/internal/config"
	"github.com/emergingrobotics/ghax/internal/provider/anthropic"
	"github.com/emergingrobotics/ghax/internal/provider/local"
	"github.com/emergingrobotics/ghax/internal/provider/mock"
	"github.com/emergingrobotics/ghax/internal/provider/openai"
)

// Build returns a provider for the given config. model overrides the config's
// default model when non-empty.
func Build(ctx context.Context, pc config.ProviderConfig, model string) (agent.Provider, error) {
	if model == "" {
		model = pc.Model
	}
	switch pc.Type {
	case "openai":
		c := openai.New(pc.BaseURL, pc.APIKey(), model, pc.Headers)
		c.Params = pc.Params
		return c, nil
	case "anthropic":
		return anthropic.New(pc.BaseURL, pc.APIKey(), model, pc.Headers), nil
	case "local":
		return local.Build(ctx, pc.BaseURL, model, pc.Headers, pc.Params)
	case "mock":
		return newMock(), nil
	default:
		return nil, fmt.Errorf("unknown provider type %q", pc.Type)
	}
}

// newMock returns an offline provider that echoes the last user message. It
// makes ghax fully runnable without a model backend, for demos and tests.
func newMock() *mock.Provider {
	p := mock.New()
	p.Meta = agent.ModelMeta{Name: "mock", Provider: "mock", ContextTokens: 8192, SupportsTools: true}
	p.Responder = func(req agent.Request) mock.Turn {
		return mock.Turn{Text: "[mock] " + lastUserText(req.Items)}
	}
	return p
}

func lastUserText(items []agent.Item) string {
	for i := len(items) - 1; i >= 0; i-- {
		if items[i].Kind == agent.ItemUserText {
			return items[i].Text
		}
	}
	return "(no input)"
}

// Package app wires the resolved configuration into a runnable agent: it
// builds the provider, toolset, herdr client, and session store, and hosts the
// three drivers (oneshot, interactive, observe). It is the only place that
// depends on every other package, keeping the leaf packages decoupled.
package app

import (
	"context"
	"fmt"
	"time"

	"github.com/emergingrobotics/ghax/internal/agent"
	"github.com/emergingrobotics/ghax/internal/config"
	"github.com/emergingrobotics/ghax/internal/herdr"
	"github.com/emergingrobotics/ghax/internal/provider"
	"github.com/emergingrobotics/ghax/internal/session"
	"github.com/emergingrobotics/ghax/internal/tool"
)

// App holds everything one run needs.
type App struct {
	cfg      *config.Config
	resolved config.Resolved
	deps     agent.Deps
	herdr    *herdr.Client
	sessions *session.Store
	cwd      string
	shape    string

	log   *agent.Log
	meta  session.Meta
	usage agent.Usage // accumulated across the session, for /usage
}

// Build assembles an App from config and the effective overrides.
func Build(ctx context.Context, cfg *config.Config, ov config.Overrides, cwd string) (*App, error) {
	resolved, err := config.Resolve(cfg, ov)
	if err != nil {
		return nil, err
	}

	prov, err := provider.Build(ctx, resolved.Provider, resolved.Model)
	if err != nil {
		return nil, err
	}

	sub := subRunner(cfg, cwd)
	tools, err := tool.Select(tool.Core(sub), resolved.Tools)
	if err != nil {
		return nil, err
	}

	sessions, err := session.Open()
	if err != nil {
		return nil, err
	}

	hc := herdr.New(herdr.Detect())
	shapeName := ov.Shape
	if shapeName == "" {
		shapeName = cfg.DefaultShape
	}
	hc.ReportMetadata(map[string]string{
		"shape":    orNone(shapeName),
		"model":    prov.Model().Name,
		"provider": prov.Model().Provider,
	})

	return &App{
		cfg:      cfg,
		resolved: resolved,
		deps: agent.Deps{
			Provider: prov,
			Tools:    tools,
			Options:  agent.Options{Model: resolved.Model, Effort: resolved.Effort},
			System:   resolved.System,
			Cwd:      cwd,
			MaxTurns: resolved.MaxTurns,
			Limits:   agent.ToolLimits{Timeout: 2 * time.Minute},
			Clock:    time.Now,
		},
		herdr:    hc,
		sessions: sessions,
		cwd:      cwd,
		shape:    shapeName,
		log:      agent.NewLog(),
		meta:     session.Meta{ID: session.NewID(), Cwd: cwd, Shape: shapeName},
	}, nil
}

// Resume loads a prior session into the app by id.
func (a *App) Resume(id string) error {
	meta, items, err := a.sessions.Load(id)
	if err != nil {
		return err
	}
	a.log = agent.NewLog()
	a.log.Load(items)
	a.meta = meta
	return nil
}

// ResumeLatest loads the most recent session for the working directory, if any.
// It reports whether a session was found.
func (a *App) ResumeLatest() (bool, error) {
	id, err := a.sessions.Latest(a.cwd)
	if err != nil || id == "" {
		return false, err
	}
	return true, a.Resume(id)
}

// SessionID returns the current session id (for resume hints).
func (a *App) SessionID() string { return a.meta.ID }

// save persists the current log to the session file.
func (a *App) save() error {
	a.meta.Cwd = a.cwd
	a.meta.Shape = a.shape
	a.meta.Model = a.deps.Provider.Model().Name
	a.meta.Observe = a.resolved.Loop == config.LoopObserve
	return a.sessions.Save(a.meta, a.log.Items())
}

// Loop reports the resolved loop mode.
func (a *App) Loop() config.LoopMode { return a.resolved.Loop }

// summarizer builds a compaction summarizer backed by the active provider, so
// /compact works against whatever model this app is pointed at, local or cloud.
func (a *App) summarizer() agent.Summarizer {
	return agent.NewProviderSummarizer(a.deps.Provider, a.deps.Options)
}

// Observe returns the resolved observe config, or nil.
func (a *App) Observe() *config.ObserveConfig { return a.resolved.Observe }

// subRunner builds the task tool's sub-run executor: it resolves the named
// shape, builds a provider and (task-free) toolset for it, runs a bounded
// user-turn on a fresh log, and returns the final assistant text.
func subRunner(cfg *config.Config, cwd string) tool.SubRunner {
	return func(ctx context.Context, shape, prompt string) (string, error) {
		resolved, err := config.Resolve(cfg, config.Overrides{Shape: shape})
		if err != nil {
			return "", err
		}
		prov, err := provider.Build(ctx, resolved.Provider, resolved.Model)
		if err != nil {
			return "", err
		}
		tools, err := tool.Select(tool.Core(nil), resolved.Tools) // no nested task tool
		if err != nil {
			return "", err
		}
		dep := agent.Deps{
			Provider: prov,
			Tools:    tools,
			Options:  agent.Options{Model: resolved.Model, Effort: resolved.Effort},
			System:   resolved.System,
			Cwd:      cwd,
			MaxTurns: resolved.MaxTurns,
			Limits:   agent.ToolLimits{Timeout: 2 * time.Minute},
		}
		log := agent.NewLog()
		if _, err := agent.Run(ctx, log, dep, agent.UserInput{Text: prompt}, agent.DriverHooks{}); err != nil {
			return "", err
		}
		items := log.Items()
		for i := len(items) - 1; i >= 0; i-- {
			if items[i].Kind == agent.ItemAssistantText {
				return items[i].Text, nil
			}
		}
		return "", fmt.Errorf("sub-run produced no answer")
	}
}

func orNone(s string) string {
	if s == "" {
		return "default"
	}
	return s
